{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Mithramycin, a large glycosylated antitumor polyketide, achieved only a peak CSF:plasma ratio of 0.12 in monkeys with little material in normal brains, indicating that large glycosidic drugs of this class do not achieve meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Erythromycin, a large macrolide glycoside, showed poor CSF penetration in humans even with meningeal inflammation, with CSF levels far below serum levels, supporting that large glycosidic substrates of efflux transporters have inadequate CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Digitoxin, a cardiac glycoside, exhibited a very low CSF/plasma ratio (0.01-0.03) in dogs, demonstrating that glycosidic drugs with multiple sugar moieties are effectively excluded from the CNS.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Epimedin B, a multi-glycoside flavonoid, showed the lowest brain concentration among tissues in rats and hardly passed the blood-brain barrier, consistent with poor CNS penetration of highly glycosylated polar molecules.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query molecule is doxorubicin, a large anthracycline glycoside and known P-gp/BCRP substrate with intrinsically poor BBB penetration. Co-treatment with cyclosporine may inhibit P-gp but does not overcome the multiple efflux and physicochemical barriers, and the provided evidence from analogous large glycosides uniformly shows inadequate CNS access. Therefore, meaningful CNS access is not predicted.",
  "evidence_gaps": [
    "No direct experimental record for doxorubicin itself under cyclosporine co-treatment is provided.",
    "The effect of cyclosporine on doxorubicin brain uptake is not quantified in the supplied evidence.",
    "CSF/plasma ratios from large glycosides may not fully predict unbound brain concentrations for doxorubicin."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

